1. /// Parses a "quantity,price" line into a total cost.
2. ///
3. /// Uses the `?` operator to short-circuit on parse errors. If either field
4. /// fails to parse, the error is propagated to the caller instead of panicking.
5. pub fn parse_line_total(line: &str) -> Result<u64, std::num::ParseIntError> {
6.     let mut parts = line.split(',');
7.     let quantity: u64 = parts.next().unwrap_or("").trim().parse()?;
8.     let price: u64 = parts.next().unwrap_or("").trim().parse()?;
9.     Ok(quantity * price)
10. }
11. 
12. /// Returns the first stock level at or below the reorder threshold.
13. pub fn first_below_threshold(levels: &[u32], threshold: u32) -> Option<u32> {
14.     levels.iter().copied().find(|&l| l <= threshold)
15. }
16. 
17. #[cfg(test)]
18. mod tests {
19.     use super::*;
20. 
21.     #[test]
22.     fn parses_a_valid_line() {
23.         assert_eq!(parse_line_total("3, 10").unwrap(), 30);
24.     }
25. 
26.     // Note: no test exercises the error path of parse_line_total, so the `?`
